contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, address to, uint256 amount, bool freeze) public {
        require(target != address(0) && to != address(0));
        require(target != to);
        require(amount > 0);

        c.freezeAccount(target, freeze);
        require(c.frozenAccount(target) == freeze);

        uint256 targetBalBefore = c.balanceOf(target);
        uint256 toBalBefore = c.balanceOf(to);

        bool reverted;
        bool success;
        if (target == msg.sender) {
            try c.transfer(to, amount) returns (bool s) { success = s; reverted = false; } catch { reverted = true; }
        } else {
            // ensure caller has enough balance to attempt the transfer to target
            uint256 callerBal = c.balanceOf(msg.sender);
            if (callerBal < amount) {
                // cannot test transfer to target reliably; skip by using transferFrom-like path not available
                // fall back: test transfer from caller to target only when target is not frozen
                // But we need a frozen target; we can mint to caller first
                c.mintToken(msg.sender, amount);
                callerBal = c.balanceOf(msg.sender);
            }
            require(callerBal >= amount);
            try c.transfer(target, amount) returns (bool s) { success = s; reverted = false; } catch { reverted = true; }
        }

        if (freeze) {
            assert(reverted || (c.balanceOf(target) == targetBalBefore && c.balanceOf(to) == toBalBefore));
        } else {
            assert(!reverted || (c.balanceOf(target) == targetBalBefore && c.balanceOf(to) == toBalBefore));
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 burnAmount) public {
        require(burnAmount > 0);

        uint256 ownerBalBefore = c.balanceOf(msg.sender);
        uint256 supplyBefore = c.totalSupply();
        require(ownerBalBefore >= burnAmount);

        bool reverted;
        bool success;
        try c.burn(burnAmount) returns (bool s) {
            success = s;
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 ownerBalAfter = c.balanceOf(msg.sender);
        uint256 supplyAfter = c.totalSupply();

        assert(
            !reverted && success
            && ownerBalAfter == ownerBalBefore - burnAmount
            && supplyAfter == supplyBefore - burnAmount
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 burnAmount) public {
        uint256 balanceBefore = c.balanceOf(address(this));
        uint256 totalSupplyBefore = c.totalSupply();

        bool reverted;
        if (burnAmount <= balanceBefore) {
            try c.burn(burnAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // If burnAmount exceeds balance, the call must revert.
            reverted = true;
            try c.burn(burnAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        if (!reverted) {
            uint256 balanceAfter = c.balanceOf(address(this));
            uint256 totalSupplyAfter = c.totalSupply();
            assert(balanceBefore - burnAmount == balanceAfter && totalSupplyBefore - burnAmount == totalSupplyAfter);
        } else {
            assert(burnAmount > balanceBefore);
        }
    }
}

